            float wave = int(amzp_style) == 10 ? sin(cr * wv * 6.2831853) : abs(fract(cr * wv) - 0.5) * 4.0 - 1.0;
            float amp = clamp(0.1 * amzp_strength, 0.0, 0.45);
            m = thr(v * (1.0 - 2.0 * amp) + amp + amp * wave, C, k);
        } else if (int(amzp_style) == 12) {
            R = pageRoll(C);
            done = true;
        } else if (int(amzp_style) == 13) {
            R = boxFlip(C);
            done = true;
        } else if (int(amzp_style) == 14) {
            float scl = 1.0 + C * amzp_strength * 3.0;
            float2 uz = cP + (uv - cP) / scl;
            R = fillOut(layerAt(fromP(uz)), smoothstep(0.1, 1.0, C));
            done = true;
        } else if (int(amzp_style) == 15) {
            float an = C * amzp_strength * 3.14159;
            float2 p = (uv - cP) * float2(asp, 1.0);
            p = advRot(p, an) / (1.0 + C * amzp_strength * 1.5);
            float2 us = cP + p / float2(asp, 1.0);
            R = fillOut(layerAt(fromP(us)), smoothstep(0.15, 1.0, C));
            done = true;
        } else if (int(amzp_style) == 16) {
            float2 p = (uv - cP) * float2(asp, 1.0);
            float r = length(p);
            float an = C * amzp_strength * 8.0 * (1.0 - smoothstep(0.0, 0.9, r));
            p = advRot(p, an);
            float2 us = cP + p / float2(asp, 1.0);
            R = fillOut(layerAt(fromP(us)), smoothstep(0.25, 1.0, C));
            done = true;
        } else if (int(amzp_style) == 17) {
            float s = pow(sin(C * 3.14159265), 0.7);
            float cnt = mix(W.x, max(amzp_count, 1.0), s);
            float2 sc = float2(cnt, cnt / asp);
            float2 us = (floor(uv * sc) + 0.5) / sc;
            R = fillOut(layerAt(fromP(us)), smoothstep(0.42, 0.58, C));
            done = true;
        } else if (int(amzp_style) == 18) {
            float2 dv = float2(1.0, 0.0);
            if (int(amzp_dirMode) == 1) dv = float2(-1.0, 0.0);
            else if (int(amzp_dirMode) == 2) dv = float2(0.0, 1.0);
            else if (int(amzp_dirMode) == 3) dv = float2(0.0, -1.0);
            else if (int(amzp_dirMode) == 4) dv = float2(0.7071, 0.7071);
            else if (int(amzp_dirMode) == 5) dv = float2(-0.7071, -0.7071);
            float2 us = uv - dv * C * amzp_strength * 1.05;
            bool inside = us.x >= 0.0 && us.x <= 1.0 && us.y >= 0.0 && us.y <= 1.0;
            float4 l2 = inside ? layerAt(fromP(us)) : float4(0.0);
            float4 fv = fillV();
            R = (amzp_swapFill>0.5) ? fv + l2 * (1.0 - fv.a) : l2 + fv * (1.0 - l2.a);
            done = true;
        } else if (int(amzp_style) == 19) {
            float ax = cos(C * 3.14159265);
            float4 fv = fillV();
            if (C < 0.5) {
                float s = max(ax, 0.001);
                float2 us = float2((uv.x - 0.5) / s + 0.5, uv.y);
                float4 l2 = (us.x >= 0.0 && us.x <= 1.0) ? layerAt(fromP(us)) : float4(0.0);
                l2.rgb *= 0.55 + 0.45 * s;
                R = l2;
            } else {
                float w = -ax * 0.5;
                R = abs(uv.x - 0.5) < w ? float4(fv.rgb * (0.55 + 0.45 * (-ax)), fv.a) : float4(0.0);
            }
            done = true;
        } else {
            float2 p = (uv - cP) * float2(asp, 1.0);
            float d = length(p);
            float wv = sin(d * max(amzp_count, 1.0) * 1.2 - C * amzp_strength * 20.0) * 0.05 * amzp_strength * sin(C * 3.14159265);
            float2 us = uv + normalize(p + 1e-5) * wv / float2(asp, 1.0);
            R = fillOut(layerAt(fromP(us)), smoothstep(0.3, 1.0, C));
            done = true;
        }
        if (!done) {
            if (C <= 0.0) m = 0.0;
            if (C >= 1.0) m = 1.0;
            R = fillOut(lay, m);
        } else {
            if (C <= 0.0) R = lay;
            else if (C >= 1.0 && int(amzp_style) >= 14) R = fillOut(lay, 1.0);
        }
        amzOutput = R;
    }
    void amzRender() {
        nmMain();
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
